import{_ as a,o,c as i,a2 as t}from"./chunks/framework.CqpfiAoK.js";const p=JSON.parse('{"title":"Período de Estabelecimento do Sistema de Simbiose","description":"","frontmatter":{},"headers":[],"relativePath":"pt/73-共生体系建立期.md","filePath":"pt/73-共生体系建立期.md","lastUpdated":1789183869000}'),d={name:"pt/73-共生体系建立期.md"};function s(r,e,n,c,l,u){return o(),i("div",null,[...e[0]||(e[0]=[t('<h1 id="periodo-de-estabelecimento-do-sistema-de-simbiose" tabindex="-1">Período de Estabelecimento do Sistema de Simbiose <a class="header-anchor" href="#periodo-de-estabelecimento-do-sistema-de-simbiose" aria-label="Permalink to &quot;Período de Estabelecimento do Sistema de Simbiose&quot;">​</a></h1><table tabindex="0"><thead><tr><th>Item</th><th>Conteúdo</th></tr></thead><tbody><tr><td>Número do Documento</td><td>73</td></tr><tr><td>Módulo</td><td>Eras Históricas e Eventos Importantes</td></tr><tr><td>Palavras-chave Principais</td><td>Sistema de simbiose, construção institucional, reconstrução social, fundação da realidade, cinco leis complementares</td></tr></tbody></table><h2 id="i-tarefa-historica-do-periodo-de-estabelecimento-do-sistema-de-simbiose" tabindex="-1">I. Tarefa Histórica do Período de Estabelecimento do Sistema de Simbiose <a class="header-anchor" href="#i-tarefa-historica-do-periodo-de-estabelecimento-do-sistema-de-simbiose" aria-label="Permalink to &quot;I. Tarefa Histórica do Período de Estabelecimento do Sistema de Simbiose&quot;">​</a></h2><p>O Período de Estabelecimento do Sistema de Simbiose é o período de construção institucional da civilização de simbiose de âncora, correspondendo à fase de &quot;fundação da realidade&quot; no caminho de ascensão de quatro estágios. Esta era tem como ponto de partida a assinatura da Carta de Simbiose e como ponto final a abertura completa dos trezentos sistemas fundamentais de cultivo, e sua tarefa histórica central é transformar as disposições principistas da carta em sistemas sociais operacionais, completando a implementação da &quot;ideia&quot; para a &quot;realidade&quot;.</p><p>A duração temporal do Período de Estabelecimento do Sistema de Simbiose é de aproximadamente séculos. Neste período, a civilização de simbiose completou a construção institucional abrangente do sistema jurídico, do sistema social, da garantia de educação, saúde e moradia, e do mecanismo de distribuição econômica, lançando uma sólida base social para a subsequente popularização do cultivo e os avanços tecnológicos.</p><h2 id="ii-estabelecimento-do-sistema-juridico" tabindex="-1">II. Estabelecimento do Sistema Jurídico <a class="header-anchor" href="#ii-estabelecimento-do-sistema-juridico" aria-label="Permalink to &quot;II. Estabelecimento do Sistema Jurídico&quot;">​</a></h2><p>O estabelecimento do sistema jurídico é a tarefa principal do Período de Estabelecimento do Sistema de Simbiose. A civilização de simbiose toma a &quot;Constituição da Simbiose&quot; como lei fundamental e gradualmente estabelece um quadro jurídico completo:</p><table tabindex="0"><thead><tr><th>Nível Jurídico</th><th>Lei Central</th><th>Conteúdo Principal</th></tr></thead><tbody><tr><td>Lei fundamental</td><td>Constituição da Simbiose</td><td>Estabelece o sistema fundamental da civilização, os direitos e deveres básicos dos cidadãos e a estrutura de governança</td></tr><tr><td>Lei básica</td><td>Lei do Trabalho da Simbiose</td><td>Garante os direitos trabalhistas, estabelece o princípio de distribuição de mais trabalho, mais ganho</td></tr><tr><td>Lei básica</td><td>Lei de Proteção ao Consumidor</td><td>Protege os direitos legítimos dos seres no consumo e nos serviços</td></tr><tr><td>Lei de garantia</td><td>Lei de Garantia Educacional</td><td>Estabelece a educação básica gratuita e o sistema de educação superior aberto</td></tr><tr><td>Lei de garantia</td><td>Lei de Garantia de Saúde</td><td>Estabelece o sistema de saúde pública gratuita e de garantia de saúde no cultivo</td></tr><tr><td>Lei de garantia</td><td>Lei de Garantia Habitacional</td><td>Garante que cada ser tenha o direito básico à moradia</td></tr><tr><td>Lei de garantia</td><td>Lei de Proteção Ambiental</td><td>Estabelece o sistema de proteção ecológica e de prevenção e controle da poluição energética</td></tr><tr><td>Lei regulatória</td><td>Lei Antimonopólio</td><td>Proíbe o monopólio do cultivo, o monopólio tecnológico e o monopólio de recursos</td></tr></tbody></table><p>Este sistema jurídico de &quot;uma constituição, duas leis básicas, cinco leis de garantia, uma lei regulatória&quot; constitui a espinha dorsal institucional da civilização de simbiose. O processo de elaboração das leis reflete plenamente o princípio do &quot;progresso conjunto de todas as raças&quot;, com representantes de todas as principais raças participando da legislação, garantindo que as leis possam atender às necessidades de diferentes formas de vida.</p><h2 id="iii-reconstrucao-do-sistema-social" tabindex="-1">III. Reconstrução do Sistema Social <a class="header-anchor" href="#iii-reconstrucao-do-sistema-social" aria-label="Permalink to &quot;III. Reconstrução do Sistema Social&quot;">​</a></h2><p>Sob o quadro jurídico, a civilização de simbiose realizou uma reconstrução abrangente do sistema social:</p><h3 id="_3-1-reconstrucao-do-sistema-educacional" tabindex="-1">3.1 Reconstrução do Sistema Educacional <a class="header-anchor" href="#_3-1-reconstrucao-do-sistema-educacional" aria-label="Permalink to &quot;3.1 Reconstrução do Sistema Educacional&quot;">​</a></h3><ul><li>Estabelecimento de um sistema educacional gratuito desde a iniciação até o ensino superior, com o conhecimento básico de engenharia de leis listado como conteúdo de educação geral</li><li>Abolição do sistema de monopólio mestre-discípulo dos métodos de cultivo, substituído por uma rede aberta de mentores</li><li>Estabelecimento de um mecanismo de avaliação educacional personalizada, recomendando sistemas de cultivo adequados de acordo com as características de cada ser</li></ul><h3 id="_3-2-reconstrucao-do-sistema-de-saude" tabindex="-1">3.2 Reconstrução do Sistema de Saúde <a class="header-anchor" href="#_3-2-reconstrucao-do-sistema-de-saude" aria-label="Permalink to &quot;3.2 Reconstrução do Sistema de Saúde&quot;">​</a></h3><ul><li>Estabelecimento de um sistema de saúde pública gratuita, aplicando os resultados do cultivo do sistema de ciclo de vida no tratamento de doenças</li><li>Estabelecimento de um sistema de monitoramento da saúde no cultivo, monitorando em tempo real o estado físico e mental dos cultivadores para prevenir desvios perigosos</li><li>Estabelecimento de fluxos especiais de tratamento médico e ético para seres estranhos e corpos de substituição das trevas</li></ul><h3 id="_3-3-reconstrucao-da-moradia-e-do-meio-ambiente" tabindex="-1">3.3 Reconstrução da Moradia e do Meio Ambiente <a class="header-anchor" href="#_3-3-reconstrucao-da-moradia-e-do-meio-ambiente" aria-label="Permalink to &quot;3.3 Reconstrução da Moradia e do Meio Ambiente&quot;">​</a></h3><ul><li>Estabelecimento de um sistema de garantia habitacional básica, garantindo que cada ser tenha um espaço de moradia seguro e confortável</li><li>Uso da tecnologia de extensão espacial para expandir a área habitacional em terras limitadas, aliviando a pressão populacional</li><li>Estabelecimento de um mecanismo de restauração ecológica, usando o sistema de ciclo de vida para restaurar o meio ambiente destruído na Era Pré-Âncora</li></ul><h3 id="_3-4-reconstrucao-da-distribuicao-economica" tabindex="-1">3.4 Reconstrução da Distribuição Econômica <a class="header-anchor" href="#_3-4-reconstrucao-da-distribuicao-economica" aria-label="Permalink to &quot;3.4 Reconstrução da Distribuição Econômica&quot;">​</a></h3><ul><li>Estabelecimento do mecanismo de contratos de produção conjunta, distribuindo de forma justa os recursos de cultivo e os recursos públicos de acordo com a contribuição e a necessidade</li><li>Abolição do sistema de herança de recursos, proibindo qualquer organização ou indivíduo de monopolizar recursos-chave</li><li>Estabelecimento de um sistema de medição padronizada de energia, fornecendo uma base tecnológica para a distribuição justa</li></ul><h2 id="iv-pratica-dos-cinco-tipos-de-civilizacao-simbiotica" tabindex="-1">IV. Prática dos Cinco Tipos de Civilização Simbiótica <a class="header-anchor" href="#iv-pratica-dos-cinco-tipos-de-civilizacao-simbiotica" aria-label="Permalink to &quot;IV. Prática dos Cinco Tipos de Civilização Simbiótica&quot;">​</a></h2><p>No processo de construção institucional, diferentes planos e regiões desenvolveram cinco tipos de civilização simbiótica de acordo com suas próprias características históricas, culturais e raciais:</p><table tabindex="0"><thead><tr><th>Tipo</th><th>Características Centrais</th><th>Região Típica</th></tr></thead><tbody><tr><td>Tipo intensivo do Leste Asiático</td><td>Alta densidade populacional, uso eficiente de recursos, tradição coletivista</td><td>Região de assentamento oriental da raça humana</td></tr><tr><td>Tipo de bem-estar nórdico</td><td>Alta garantia de bem-estar, liberdade individual, harmonia entre o homem e a natureza</td><td>Região da raça élfica em zonas de alta neve</td></tr><tr><td>Tipo多元 da América do Norte</td><td>Coabitação de múltiplas raças, tolerância cultural, impulsionado pela inovação</td><td>Região de múltiplas raças do Novo Mundo</td></tr><tr><td>Tipo social continental europeu</td><td>Economia social de mercado, autonomia setorial, herança cultural</td><td>Região de renascimento de civilizações antigas</td></tr><tr><td>Tipo de recuperação em desenvolvimento</td><td>Industrialização rápida, prioridade de infraestrutura, sociedade de aprendizado</td><td>Regiões posteriores de ex-áreas de predação</td></tr></tbody></table><p>Os cinco tipos não são mutuamente exclusivos, mas sim práticas institucionais com focos diferentes sob o quadro unificado da Constituição da Simbiose. Eles mantêm uma comunicação e competição estreitas entre si, enriquecendo conjuntamente o conteúdo institucional da civilização de simbiose.</p><h2 id="v-construcao-inicial-da-infraestrutura-de-ancoras" tabindex="-1">V. Construção Inicial da Infraestrutura de Âncoras <a class="header-anchor" href="#v-construcao-inicial-da-infraestrutura-de-ancoras" aria-label="Permalink to &quot;V. Construção Inicial da Infraestrutura de Âncoras&quot;">​</a></h2><p>O Período de Estabelecimento do Sistema de Simbiose também é o período de construção em larga escala da infraestrutura de âncoras:</p><ul><li>A âncora principal cósmica de primeiro nível foi concluída no início da era, tornando-se o núcleo da rede de âncoras de todo o universo</li><li>As âncoras principais de plano de segundo nível foram implantadas sucessivamente nos principais planos, formando inicialmente a capacidade de agendamento energético em nível de plano</li><li>As âncoras regionais de terceiro nível cobrem áreas de alta densidade populacional, fornecendo suporte energético para a popularização do cultivo</li><li>As âncoras comunitárias de quarto nível começaram a ser implantadas em caráter experimental, acumulando experiência para a cobertura completa subsequente</li></ul><p>A construção da infraestrutura de âncoras segue o princípio de &quot;planejamento unificado, construção hierárquica&quot;, garantindo o uso eficiente dos recursos e a equidade da cobertura.</p><h2 id="conclusao" tabindex="-1">Conclusão <a class="header-anchor" href="#conclusao" aria-label="Permalink to &quot;Conclusão&quot;">​</a></h2><p>O Período de Estabelecimento do Sistema de Simbiose é a &quot;era da fundação&quot; da civilização de simbiose de âncora. Ele usou séculos para completar a transformação institucional fundamental da ordem predatória da Era Pré-Âncora para a ordem simbiótica. O estabelecimento do sistema jurídico forneceu à civilização um quadro de regras, a reconstrução do sistema social forneceu garantias reais a todos os seres, a prática dos cinco tipos de civilização forneceu caminhos多元 para a inovação institucional, e a construção da infraestrutura de âncoras lançou a base material para o desenvolvimento subsequente. Quando chegou o momento da abertura completa dos trezentos sistemas fundamentais de cultivo, a civilização de simbiose já estava totalmente preparada institucionalmente.</p><h2 id="documentos-relacionados" tabindex="-1">Documentos Relacionados <a class="header-anchor" href="#documentos-relacionados" aria-label="Permalink to &quot;Documentos Relacionados&quot;">​</a></h2><ul><li>72-Era do Despertar da Âncora</li><li>74-Evento de Abertura dos Trezentos Sistemas</li><li>40-Programa Geral da Constituição da Simbiose</li></ul>',31)])])}const b=a(d,[["render",s]]);export{p as __pageData,b as default};
